              $out_evento_logo = $this->Ini->path_imag_temp . "/sc_evento_logo_" . $_SESSION['scriptcase']['sc_num_img'] . session_id() . $Ext_File;   
              $_SESSION['scriptcase']['sc_num_img']++ ; 
              $arq_evento_logo = fopen($this->Ini->root . $out_evento_logo, "w") ;  
