              $sc_obj_img->setManterAspecto(true);
              $sc_obj_img->createImg($this->Ini->root . $out_evento_logo);
              $Img_Word_Ext = "jpeg";
              if (!is_file($this->Ini->root . $out_evento_logo)) {
                  $out_evento_logo = $out1_evento_logo;
                  $Img_Dim = " width=\"30\" height=\"30\"";
                  $Img_Word_Ext = $Ext_File;
              }
              $loc_img_word = $this->Ini->root . $out_evento_logo;
              if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_eventos_rsvp']['doc_word'] || $_SESSION['sc_session'][$this->Ini->sc_page]['grid_eventos_rsvp']['embutida_opcao'] == "doc_word" || $this->Ini->sc_export_ajax_img) 
