 function NM_grid_evento_id_interno()
 {
      global $nm_saida;
      $actionbarFieldLinkHiddenClass = '';
      if (!isset($this->NM_cmp_hidden['evento_id_interno']) || $this->NM_cmp_hidden['evento_id_interno'] != "off") { 
          if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_eventos_rsvp']['opcao'] == "pdf" && isset($_SESSION['nm_session']['sys_wkhtmltopdf_show_html_content']) && $_SESSION['nm_session']['sys_wkhtmltopdf_show_html_content'] == 'Y') {
              $conteudo = NM_encode_input(sc_strip_script($this->evento_id_interno));
              $conteudo_original = NM_encode_input(sc_strip_script($this->evento_id_interno));
          }
          else {
              $conteudo = sc_strip_script($this->evento_id_interno); 
              $conteudo_original = sc_strip_script($this->evento_id_interno); 
          }
          if ($conteudo === "") 
          { 
              $conteudo = "&nbsp;" ;  
              $graf = "" ;  
          } 
          $str_tem_display = $conteudo;
          if(!empty($str_tem_display) && $str_tem_display != '&nbsp;' && !$_SESSION['sc_session'][$this->Ini->sc_page]['grid_eventos_rsvp']['proc_pdf'] && !$_SESSION['sc_session'][$this->Ini->sc_page]['grid_eventos_rsvp']['embutida'] && !empty($conteudo)) 
          { 
              $str_tem_display = $this->getFieldHighlight('quicksearch', 'evento_id_interno', $str_tem_display, $conteudo_original); 
              $str_tem_display = $this->getFieldHighlight('advanced_search', 'evento_id_interno', $str_tem_display, $conteudo_original); 
          } 
          $conteudo = $str_tem_display; 
          $classColFld = "";
          if (!$_SESSION['sc_session'][$this->Ini->sc_page]['grid_eventos_rsvp']['embutida'] && $_SESSION['sc_session'][$this->Ini->sc_page]['grid_eventos_rsvp']['opcao_print'] != 'print' && $_SESSION['sc_session'][$this->Ini->sc_page]['grid_eventos_rsvp']['opcao'] != 'pdf') {
              $classColFld = " sc-col-fld sc-col-fld-" . $this->grid_fixed_column_no;
          }
          if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_eventos_rsvp']['proc_pdf'])
          {
              $this->SC_nowrap = "";
          }
          else
          {
              $this->SC_nowrap = "";
          }
   $nm_saida->saida("     <TD rowspan=\"" . $this->Rows_span . "\" class=\"" . $this->css_line_fonf . $this->css_sep . $this->css_evento_id_interno_grid_line . $actionbarFieldLinkHiddenClass . "\"  style=\"" . $this->Css_Cmp['css_evento_id_interno_grid_line'] . "\" " . $this->SC_nowrap . " align=\"\" valign=\"top\"   HEIGHT=\"0px\"><span id=\"id_sc_field_evento_id_interno_" . $this->SC_seq_page . "\">" . $conteudo . "</span></TD>\r\n");
