 function NM_calc_span()
 {
   $this->NM_colspan  = 32;
   if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_eventos_rsvp']['opc_psq'])
   {
       $this->NM_colspan++;
   }
   if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_eventos_rsvp']['embutida'] || $_SESSION['sc_session'][$this->Ini->sc_page]['grid_eventos_rsvp']['opcao'] == "pdf" || $_SESSION['sc_session'][$this->Ini->sc_page]['grid_eventos_rsvp']['embutida_pdf'] == "pdf")
   {
       $this->NM_colspan--;
   } 
   foreach ($this->NM_cmp_hidden as $Cmp => $Hidden)
   {
       if ($Hidden == "off" && !isset($this->All_nested_line[$Cmp]))
       {
           $this->NM_colspan--;
       }
   }
   if ($_SESSION['sc_session'][$this->Ini->sc_page]['grid_eventos_rsvp']['embutida_grid'])
   {
