       $nm_saida->saida("}\r\n");
       $nm_saida->saida("function get_json_dyn_search_and_or(Tab_obj_dyn_search)\r\n");
       $nm_saida->saida("{\r\n");
       $nm_saida->saida("    json_dyn_search = {};\r\n");
