       $nm_saida->saida("         }\r\n");
       $nm_saida->saida("     }\r\n");
       $nm_saida->saida("     function ajax_replace_dyn_search_js(obj, seq)\r\n");
       $nm_saida->saida("     {\r\n");
$nm_saida->saida("         nm_dynamicsearch_backup();\r\n");
$nm_saida->saida("         Tab_obj_dyn_search[seq] = obj.value;\r\n");
