       $nm_saida->saida("     function nm_dynamicsearch_backup()\r\n");
       $nm_saida->saida("     {\r\n");
       $nm_saida->saida("         if(!nm_dynamicsearch_getChange())\r\n");
       $nm_saida->saida("         {\r\n");
