   function grid_search_add_tag()
   {
       $lin_obj  = "";
       $All_cmp_search = array('evento_id','evento_nome','evento_dt_realizacao','evento_dt_conclusao','evento_status','evento_municipio');
       $nmgp_tab_label = $_SESSION['sc_session'][$this->Ini->sc_page]['grid_eventos_rsvp']['pesq_tab_label'];
       if (!empty($nmgp_tab_label))
       {
          $nm_tab_campos = explode("?@?", $nmgp_tab_label);
          $nmgp_tab_label = array();
          foreach ($nm_tab_campos as $cada_campo)
          {
              $parte_campo = explode("?#?", $cada_campo);
              $nmgp_tab_label[$parte_campo[0]] = $parte_campo[1];
          }
       }
       if (isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_eventos_rsvp']['grid_pesq']) && is_array($_SESSION['sc_session'][$this->Ini->sc_page]['grid_eventos_rsvp']['grid_pesq']) && count($_SESSION['sc_session'][$this->Ini->sc_page]['grid_eventos_rsvp']['grid_pesq']) < 6)
       {
           $lin_obj .= "<table id='id_grid_search_all_cmp' cellpadding=0 cellspacing=0>";
           foreach ($All_cmp_search as $cada_cmp)
           {
               if (!isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_eventos_rsvp']['grid_pesq'][$cada_cmp]))
               {
                   $lin_obj .= "  <tr>";
                   $lin_obj .= "    <td class='scBtnGrpBackground'>";
                   $lin_obj .= "        <div class='scBtnGrpText' style='cursor:pointer;' onClick=\"ajax_add_grid_search(this, 'grid', '" . $cada_cmp . "'); return false;\">";
                   $lin_obj .= "            " . $nmgp_tab_label[$cada_cmp] . "";
                   $lin_obj .= "        </div>";
                   $lin_obj .= "    </td>";
                   $lin_obj .= "  </tr>";
               }
           }
           $lin_obj .= "</table>";
       }
       return $lin_obj;
   }
