   function html_interativ_search()
   {
       global $nm_saida;
       $bol_refin_use_modal = true;
       if($_SESSION['scriptcase']['proc_mobile'])
       {
           $bol_refin_use_modal = false;
       }
       $_SESSION['sc_session'][$this->Ini->sc_page]['grid_eventos_rsvp']['int_search_label'] = array();
       if (!isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_eventos_rsvp']['int_search_dados']))
       {
           $_SESSION['sc_session'][$this->Ini->sc_page]['grid_eventos_rsvp']['int_search_dados'] = array();
       }
       $_SESSION['sc_session'][$this->Ini->sc_page]['grid_eventos_rsvp']['int_search_sql']   = array();
       if (!isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_eventos_rsvp']['interativ_search']))
       {
           $_SESSION['sc_session'][$this->Ini->sc_page]['grid_eventos_rsvp']['interativ_search'] = array();
