   function interativ_search_id_app($bol_refin_use_modal)
   {
       $cle_disp = (isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_eventos_rsvp']['interativ_search']["id_app"])) ? "" : "none";
       $exp_disp = (isset($_SESSION['sc_session'][$this->Ini->sc_page]['grid_eventos_rsvp']['interativ_search']["id_app"])) ? "none" : "";
       $displ_open= true;
       $lin_obj  = "    <div id=\"div_int_id_app\">";
       $lin_obj .= "    <table width='100%' cellspacing=0 cellpadding=0>";
       $lin_obj .= "     <tr>";
