function GetSaldoHotel($evento_id,$id_hotel) {
$_SESSION['scriptcase']['grid_eventos_rsvp']['contr_erro'] = 'on';
  	
	date_default_timezone_set('America/Sao_Paulo');
	$valor_y = 'Y';		
	$valor_zero = '0';
	$ret = 0;
	$valor_room = 'SIM';
		
	$sql = "
